    $stream="BT\n/F1 10 Tf\n50 780 Td\n";foreach($lines as $line){$line=substr(preg_replace('/[^\x20-\x7E]/','?',(string)$line),0,110);$stream.='('.str_replace(['\\','(',')'],['\\\\','\\(','\\)'],$line).") Tj\n0 -14 Td\n";}$stream.='ET';$objects[3]='<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>';$objects[4]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>';$objects[5]='<< /Length '.strlen($stream).' >>\nstream\n'.$stream.'\nendstream';$pdf="%PDF-1.4\n";$offsets=[0];for($i=1;$i<=5;$i++){$offsets[$i]=strlen($pdf);$pdf.=$i." 0 obj\n".$objects[$i]."\nendobj\n";}$xref=strlen($pdf);$pdf.='xref\n0 6\n0000000000 65535 f \n';for($i=1;$i<=5;$i++)$pdf.=sprintf("%010d 00000 n \n",$offsets[$i]);$pdf.='trailer << /Size 6 /Root 1 0 R >>\nstartxref\n'.$xref."\n%%EOF";header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="'.basename($filename).'"');echo $pdf;exit;
